from pathlib import Path
import json,shutil,hashlib
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1]/'production/room-review'
T=ROOT/'templates'
for p in T.glob('*.json'):
 value=json.loads(p.read_text().replace('__ROOM_ID__','courtyard').replace('__FAMILY__','gameplay-room'))
 (ROOT/p.name).write_text(json.dumps(value,indent=2))
def read(n):return json.loads((ROOT/n).read_text())
def write(n,d):(ROOT/n).write_text(json.dumps(d,ensure_ascii=False,indent=2))
b=read('room-brief.json');b.update(purpose='Investigate a family memory in a Vietnamese courtyard, with unobstructed evidence circulation.',runtimeSurface='Panda3D first-person desktop, development runtime; proposed Blender revision not yet integrated.',boundsMeters=[18,16,3.8],hero={'id':'biscuit-tin','role':'Archive key and recurring family evidence container','reservedBoundsMeters':[1.8,1.2,1.4]},circulation={'description':'Three-metre south arrival; central north-south circulation; side evidence stations; 1.6 m north exit to school path.','minimumClearanceMeters':1.2},productionCamera={'viewport':[1280,720],'location':[0,-7,1.7],'target':[0,8,1.5],'verticalFovDegrees':60},performanceBudget={'maxSceneTriangles':100000,'maxVLowBytes':20000000,'maxHighTextureBytes':64000000})
b['artifacts'].update(floorPlan='plans/courtyard-floor.png',reflectedCeilingPlan='plans/courtyard-ceiling.png',wallElevations=['plans/courtyard-south-elevation.png'],visualTarget='renders/courtyard-arrival.png',openingContactSheet='masks/contact.png');write('room-brief.json',b)
p=read('props.json');p['generation']['creditsPerTexturedTask']=None
p['assets']=[{'id':'biscuit-tin','class':'hero','function':'Holds the key and evidence; returns at the ending.','description':'Worn teal enameled biscuit tin with separate removable lid.','dimensionsMeters':[.24,.24,.12],'attachmentFace':'floor','semanticFront':'positive-z','targetPolycount':1800,'intendedInstances':1,'rejectionCriteria':['Fused lid/body prevents opening','Missing flat base','Floating or cropped geometry','Unreadable scale or implausible metal thickness'],'image':{'source':'images/tin-reference.png','generator':'image_gen','prompt':'One isolated worn late-1990s teal enameled biscuit tin, cream stripe, removable closed lid, flat base, 24 cm diameter, 12 cm height, complete three-quarter silhouette, even studio light, no text or scene.','approved':False,'approvedBy':''},'attempts':[]}]
p['notes']='No account or paid budget supplied. Pricing unverified; no Meshy or Lux3D task submitted. Local Blender proposal is separate from this unapproved service workflow.';write('props.json',p)
l=read('room-layout.json');l['surfaces']=[{'id':'floor','dimensions':[18,16,.2]},{'id':'north','dimensions':[18,.3,3.6]},{'id':'south','dimensions':[18,.3,3.6]},{'id':'west','dimensions':[.3,16,3.6]},{'id':'east','dimensions':[.3,16,3.6]},{'id':'veranda-ceiling','dimensions':[18,4,.18]}];l['instances']=[{'id':'tin-1','assetId':'biscuit-tin','position':[2,6,.93]}];l['productionCamera']=b['productionCamera'];l['geometryManifest']='geometry-metadata.json';write('room-layout.json',l)
m=read('plan-metadata.json');m.update(coverage=['room-outline','cutouts','openings','exterior-apron','main-sign','ingress-props','floor-markers','barriers','columns','circulation','placed-features'],coverageNotes={'main-sign':'Area title in runtime HUD; no physical sign proposed','ingress-props':'Intentionally absent to preserve clear arrival','floor-markers':'Intentionally absent; runtime map supplies navigation','columns':'No freestanding colonnade proposed; veranda bears on perimeter walls','circulation':'Central north-south aisle plus side access shown in actual-mesh projection','barriers':'Continuous walls with scheduled Boolean openings'},roomId='courtyard',geometrySource='courtyard-FUNCTION-DRAFT.blend',completeObjectManifest='geometry-metadata.json',projection='orthographic actual design meshes; separate floor/ceiling renders');write('plan-metadata.json',m)
o=read('openings.json');o['primaryArrival']={'openingId':'arrival','exception':''};o['openings']=[]
for name,kind,w,h,sill,wall,dest in [('arrival','door',3,2.6,0,'south','Courtyard approach apron'),('exit','door',1.6,2.6,0,'north','School approach landing'),('window-west','window',2.4,1.4,1.3,'west','Exterior daylight'),('window-east','window',2.4,1.4,1.3,'east','Exterior daylight')]:
 im=Image.new('L',(256,256),0);d=ImageDraw.Draw(im);d.rectangle((32,32,223,255 if kind=='door' else 223),fill=255);im.save(ROOT/f'masks/{name}.png')
 o['openings'].append({'id':name,'kind':kind,'widthMeters':w,'heightMeters':h,'sillMeters':sill,'thresholdMeters':0,'depthMeters':.3,'wall':wall,'destination':dest,'mask':f'masks/{name}.png','cutter':f'masks/{name}-cutter.json','approved':False})
write('openings.json',o)
contact=Image.new('RGB',(1024,300),'white');draw=ImageDraw.Draw(contact)
for i,o2 in enumerate(o['openings']):contact.paste(Image.open(ROOT/o2['mask']).convert('RGB'),(i*256,30));draw.text((i*256+4,6),o2['id']+' '+str(o2['widthMeters'])+'m',fill='black')
contact.save(ROOT/'masks/contact.png')
r=read('milestone-reviews.json');r['function'].update(evidence=['plans/courtyard-floor.png','plans/courtyard-ceiling.png','images/tin-reference.png','masks/contact.png'],strangestElement='Current runtime doors are solid transition markers; the proposal provides real Boolean apertures and destinations.',notes='Awaiting human layout/reference approval. No service account/budget. Do not advance paid generation or final Form composition.');write('milestone-reviews.json',r)
f=read('final-report.json');f['postmortem']['observations']=['Five distinct dimensional Function drafts and 20 Blender renders exist.','No generated mesh has been purchased or exported.','Current game runtime uses earlier procedural development scenes.'];f['postmortem']['remainingRisks']=['Human Function approval pending','Service route lacks account, budget and current pricing','Final Form/Runtime review pending','4–6 hour duration and Windows binary unverified'];write('final-report.json',f)
# Portable review page uses real files, no external libraries or fake approvals.
html=['<!doctype html><html lang="vi"><meta charset="utf-8"><title>Duyệt bố trí — Bến Không Tên</title><style>body{background:#14201d;color:#e9e2cb;font:17px system-ui;margin:40px auto;max-width:1150px}img{max-width:100%}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}section{margin:40px 0}a{color:#dcb979}</style><h1>Bến Không Tên · Bố trí đề xuất</h1><p>Function review only. Chưa duyệt thiết kế, chưa phải cảnh hoàn thiện hoặc bản xuất trong game. Các ảnh mặt bằng được dựng trực giao từ hình học thật trong tệp Blender đề xuất. Mỗi khu vực có mặt bằng, trần, mặt đứng và góc vào.</p>']
for rid,name in [('courtyard','Sân nhà tập thể'),('school','Trường học'),('wharf','Bến sông'),('archive','Phòng hồ sơ'),('warehouse','Nhà kho')]:
 html.append(f'<section><h2>{name}</h2><div class="grid"><figure><img src="plans/{rid}-floor.png"><figcaption>Mặt bằng</figcaption></figure><figure><img src="renders/{rid}-arrival.png"><figcaption>Góc vào</figcaption></figure><figure><img src="plans/{rid}-ceiling.png"><figcaption>Trần</figcaption></figure><figure><img src="plans/{rid}-south-elevation.png"><figcaption>Mặt đứng lối vào</figcaption></figure></div><a href="{rid}-FUNCTION-DRAFT.blend">Nguồn Blender đề xuất</a></section>')
html.append('<section><h2>Vật thể chính: hộp bánh quy</h2><img width="600" src="images/tin-reference.png"><p>Ảnh tham chiếu từ image_gen; chưa có mesh Lux3D/Meshy, chưa duyệt hình ảnh.</p></section><h2>Lịch cửa và cửa sổ</h2><img src="masks/contact.png"><p>Lối vào rộng 3m; lối ra 1.6m; cửa sổ 2.4 × 1.4m. Đây là thiết kế đề xuất, chưa thay các cảnh đang chạy.</p></html>')
(ROOT/'review.html').write_text(''.join(html),encoding='utf8')
print('Review package prepared; approvals remain pending.')
